I64 ClampScore(I64 score, I64 minimum, I64 maximum)
{
    if (score < minimum) {
        return minimum;
    }

    if (score > maximum) {
        return maximum;
    }

    return score;
}

U0 Greet(U8 *name)
{
    if (!name || !*name) {
        "Hello, stranger.\n";
        return;
    }

    "Hello, %s. God says hi.\n", name;
}

I64 SumArray(I64 *values, I64 length)
{
    I64 total = 0;

    for (I64 i = 0; i < length; i++) {
        total += values[i];
    }

    return total;
}

class ScoreEntry
{
    U8 name[32];
    I64 score;
    Bool is_online;
};

ScoreEntry *PickBest(ScoreEntry *entries, I64 length)
{
    if (length <= 0) {
        return NULL;
    }

    ScoreEntry *best = &entries[0];
    for (I64 i = 1; i < length; i++) {
        if (entries[i].score > best->score) {
            best = &entries[i];
        }
    }

    return best;
}

I64 CountActive(ScoreEntry *entries, I64 length)
{
    I64 count = 0;

    for (I64 i = 0; i < length; i++) {
        if (entries[i].is_online) {
            count++;
        }
    }

    return count;
}

U0 ResetBoard(I64 *cells, I64 length, I64 value)
{
    for (I64 i = 0; i < length; i++) {
        cells[i] = value;
    }
}

Bool IsPrime(I64 value)
{
    if (value < 2) {
        return FALSE;
    }

    for (I64 divisor = 2; divisor * divisor <= value; divisor++) {
        if (value % divisor == 0) {
            return FALSE;
        }
    }

    return TRUE;
}

I64 IndexOf(I64 *values, I64 length, I64 needle)
{
    for (I64 i = 0; i < length; i++) {
        if (values[i] == needle) {
            return i;
        }
    }

    return -1;
}

U0 PrintBoard(I64 *cells, I64 width, I64 height)
{
    for (I64 y = 0; y < height; y++) {
        for (I64 x = 0; x < width; x++) {
            "%d ", cells[y * width + x];
        }
        "\n";
    }
}

I64 GodSpeaks(I64 word_count)
{
    I64 total = 0;

    for (I64 i = 0; i < word_count; i++) {
        I64 word = Rand & 0x7FFF;
        "%d ", word;
        total += word;
    }

    "\n";
    return total;
}
